import { DeleteOutlined, PlusOutlined } from '@ant-design/icons';
import { Button, Flex, Form, Input, Select, Switch, type FormInstance } from 'antd';
import { useEffect, useRef, useState } from 'react';

import type { ConnectionType } from '../../api/connections';
import { activeAuthOption, CONNECTION_FORM_SPECS, type TextField } from './connectionFormSpec';

/** Renders the type-specific config + secret form fields from CONNECTION_FORM_SPECS. */

const requiredRule = [{ required: true }];

function ConfigTextField({
  field,
  forceRequired = false,
}: {
  field: TextField;
  forceRequired?: boolean;
}) {
  const optional = field.optional && !forceRequired;
  if (field.type === 'toggle') {
    // A boolean config flag (e.g. `inventory_sync`, ADR 0040). `valuePropName` wires the Switch's
    // `checked` into the form value; an untouched toggle simply omits the key, which the backend
    // defaults to false.
    return (
      <Form.Item
        name={['config', field.name]}
        label={field.label}
        extra={field.extra}
        valuePropName="checked"
      >
        <Switch />
      </Form.Item>
    );
  }
  return (
    <Form.Item
      name={['config', field.name]}
      label={field.label}
      rules={optional ? undefined : requiredRule}
      extra={field.extra}
---spec---
    extra?: string;
    showWhen: (config: Record<string, unknown> | undefined) => boolean;
  };
  /** `config` fields that decide **where the PRIMARY credential is sent** (#1401). */
  destinationFields?: string[];
}

