export function ConnectionForm({
  type,
  connection,
  onSaved,
  onCancel,
}: {
  /** The connection type — picked on the new page, fixed from the row on edit. */
  type: ConnectionType;
  connection?: Connection;
  /** Called with the saved connection (created or updated). */
  onSaved: (connection: Connection) => void;
  onCancel: () => void;
}) {
  const { message } = App.useApp();
  const [form] = Form.useForm<FormValues>();
  const isEdit = connection !== undefined;
  const { run, loading: submitting } = useAsyncAction(`${isEdit ? 'Update' : 'Create'} failed`);
  const [testState, setTestState] = useState<TestState>('idle');
  const [testError, setTestError] = useState<string>();

  // Seed the form: an edit prefills name + config; a create seeds the new type's config defaults
  // (e.g. the auth-type) and clears any fields left over from a previously-picked type.
  useEffect(() => {
    form.resetFields();
    if (connection) {
      form.setFieldsValue({ name: connection.name, config: connection.config });
    } else {
      form.setFieldsValue({ config: initialConfigForType(type) });
    }
  }, [type, connection, form]);

  // Only the selected auth mode's passphrase rides along — a value typed under a previously-picked
  // mode is preserved in the form store after its field unmounts and must not wrap the secret.
  const buildSecret = (values: FormValues): string | undefined =>
    values.secret
      ? composeSecret(
          values.secret,
          activeAuthOption(type, values.config)?.passphraseLabel
            ? values.secretPassphrase
            : undefined,
        )
      : undefined;

  // A field changed after a test ran — the green/red badge no longer describes what would actually
  // be saved (repo precedent: Connections.tsx `clearHealth`, "the prior pass/fail no longer
  // holds").
  const onValuesChange = () => {
    if (testState !== 'idle') {
      setTestState('idle');
      setTestError(undefined);
    }
