  const onTest = async () => {
    if (isEdit) {
      setTestState('testing');
      setTestError(undefined);
      try {
        const { ok } = await testConnection(connection.id);
        setTestState(ok ? 'ok' : 'failed');
      } catch (err) {
        setTestState('failed');
        setTestError(errorMessage(err));
      }
      return;
    }
