        <Form.Item name="env" label="Environment" rules={[{ required: true }]}>
          <Select
            options={CONNECTION_ENVS.map((e) => ({ value: e, label: envLabel(e) }))}
            placeholder="Select an environment"
          />
        </Form.Item>
      )}
      {movedDestinations.length > 0 && (
        <Alert
          type="warning"
          showIcon
          style={{ marginBottom: 16 }}
          title="Re-enter the credential to move this connection"
          description={
            `Changing ${movedDestinations.join(', ')} changes where this connection's ` +
            'credential is sent, so it must be supplied again. The stored one is never ' +
            'forwarded to a new destination.'
          }
